type Forms = Partial<Record<Intl.LDMLPluralRule, string>> & { other: string }

export function plural(locale: string, count: number, forms: Forms) {
  const rule = new Intl.PluralRules(locale).select(count) // "one" | "few" | "many" | "other"
  return (forms[rule] ?? forms.other).replace("#", String(count))
}

