// fayl: lib/i18n/detect.ts
import { match } from "@formatjs/intl-localematcher"
import Negotiator from "negotiator"

export const locales = ["uz", "ru", "en"]
export const defaultLocale = "uz"

export function detectLocale(acceptLanguage: string | null) {
  const languages = new Negotiator({
    headers: { "accept-language": acceptLanguage ?? "" },
  })
    .languages()
    .filter((l) => l !== "*") // "*" Intl uchun yaroqsiz teg

  try {
    return match(languages, locales, defaultLocale)
  } catch {
    return defaultLocale // buzuq teg (masalan "xx-!!") — 500 emas, standart til
  }
}

