// fayl: app/[lang]/locale-switcher.tsx
"use client"
import Link from "next/link"
import { usePathname } from "next/navigation"

const labels = { uz: "O'zbekcha", ru: "Русский", en: "English" }

export function LocaleSwitcher({ current }: { current: string }) {
  const pathname = usePathname() // masalan "/uz/recipes/12"

  function hrefFor(locale: string) {
    const segments = pathname.split("/")
    segments[1] = locale // birinchi segment — til
    return segments.join("/")
  }

  return (
    <nav aria-label="Til">
      {Object.entries(labels).map(([locale, label]) => (
        <Link
          key={locale}
          href={hrefFor(locale)}
          hrefLang={locale}
          aria-current={locale === current ? "true" : undefined}
        >
          {label}
        </Link>
      ))}
    </nav>
  )
}

// fayl: app/[lang]/actions.ts
"use server"
import { cookies } from "next/headers"
import { redirect } from "next/navigation"

const locales = ["uz", "ru", "en"]

export async function changeLocale(formData: FormData) {
  const locale = String(formData.get("locale"))
  const path = String(formData.get("path") ?? "/")
  if (!locales.includes(locale)) return

  const store = await cookies()
  store.set("NEXT_LOCALE", locale, { path: "/", maxAge: 60 * 60 * 24 * 365, sameSite: "lax" })

  const rest = path.split("/").slice(2).join("/") // "/uz/recipes/12" → "recipes/12"
  redirect(`/${locale}/${rest}`)
}

