import type { ComponentProps } from "react"

type Props = Omit<ComponentProps<typeof Link>, "href"> & { href: string; lang: string }

export function LocaleLink({ href, lang, ...rest }: Props) {
  const isExternal = /^https?:\/\//.test(href)
  const localized = isExternal ? href : `/${lang}${href === "/" ? "" : href}`
  return <Link href={localized} {...rest} />
}

