// fayl: lib/i18n/pathnames.ts
// Ichki (papka) yo'l → har tildagi ko'rinadigan yo'l
export const pathnames: Record<string, Record<string, string>> = {
  "/recipes": { uz: "/retseptlar", ru: "/recepty", en: "/recipes" },
  "/about": { uz: "/biz-haqimizda", ru: "/o-nas", en: "/about" },
}

export function toInternal(locale: string, visible: string) {
  for (const [internal, map] of Object.entries(pathnames)) {
    if (map[locale] === visible) return internal
  }
  return visible
}

// fayl: proxy.ts
import { NextResponse, type NextRequest } from "next/server"
import { toInternal } from "@/lib/i18n/pathnames"

export function proxy(request: NextRequest) {
  const [, locale, ...rest] = request.nextUrl.pathname.split("/")
  const visible = "/" + rest.join("/")
  const internal = toInternal(locale, visible)
  if (internal === visible) return

  const url = request.nextUrl.clone()
  url.pathname = `/${locale}${internal}` // papka: app/[lang]/recipes
  return NextResponse.rewrite(url)
}

