type TextInfo = { direction: "rtl" | "ltr" }

export function getDirection(locale: string): "rtl" | "ltr" {
  const info = new Intl.Locale(locale) as Intl.Locale & { getTextInfo?: () => TextInfo; textInfo?: TextInfo }
  // getTextInfo() hamma muhitda yo'q — eski nomi textInfo, oxirida zaxira ro'yxat
