import { revalidateTag } from "next/cache"

export async function POST(request: Request) {
  if (request.headers.get("x-webhook-secret") !== process.env.REVALIDATE_SECRET) {
    return new Response(null, { status: 401 })
  }
  const { type, slug } = (await request.json()) as { type: string; slug?: string }
  revalidateTag(`${type}s`, "max")             // ro'yxat: posts
  if (slug) revalidateTag(`${type}:${slug}`, "max")  // yozuv: post:osh-retsepti
  return Response.json({ revalidated: true })
}

