export type Post = { slug: string; title: string; body: string; status: "draft" | "published" }

// Chop etilgan versiya: keshlanadi, webhook teg bo'yicha yangilaydi
export async function getPublishedPost(slug: string): Promise<Post | null> {
  "use cache"
  cacheTag("posts", `post:${slug}`)
  cacheLife("max")
  const res = await fetch(`${process.env.CMS_URL}/posts/${slug}`, {
    headers: { Authorization: `Bearer ${process.env.CMS_DELIVERY_TOKEN}` },
  })
  if (res.status === 404) return null
  if (!res.ok) throw new Error(`CMS xatosi: ${res.status}`)
  return res.json()
}

