  const res = await fetch(`${process.env.CMS_URL}/posts/${slug}?status=draft`, {
    headers: { Authorization: `Bearer ${process.env.CMS_PREVIEW_TOKEN}` },
    cache: "no-store",
  })
  if (res.status === 404) return null
  if (!res.ok) throw new Error(`CMS xatosi: ${res.status}`)
  return res.json()
}

