export async function toggleDraft(pathname: string) {
  const session = await getSession()
  // har bir Server Action — ochiq POST endpoint: rolni shu yerda tekshiramiz
  if (session?.role !== "editor") throw new Error("Ruxsat yo'q")

  const draft = await draftMode()
  if (draft.isEnabled) draft.disable()
  else draft.enable()
  redirect(pathname.startsWith("/") && !pathname.startsWith("//") ? pathname : "/")
}

