// fayl: lib/cms-fetch.ts
import "server-only"

type Options = { draft?: boolean; tags?: string[] }

export async function cmsFetch<T>(path: string, { draft = false, tags = [] }: Options = {}): Promise<T> {
  const token = draft ? process.env.CMS_PREVIEW_TOKEN : process.env.CMS_DELIVERY_TOKEN
  const res = await fetch(`${process.env.CMS_URL}${path}`, {
    headers: { Authorization: `Bearer ${token}` },
    // qoralama keshlanmaydi; chop etilgan teglar bilan Data Cache'ga tushadi
    ...(draft ? { cache: "no-store" as const } : { cache: "force-cache" as const, next: { tags } }),
  })
  if (!res.ok) throw new Error(`CMS ${res.status}: ${path}`)
  return res.json() as Promise<T>
}

