// fayl: lib/graphql.ts
import "server-only"

type GqlOptions = { draft?: boolean; tags?: string[] }

export async function gql<T>(
  query: string,
  variables: Record<string, unknown> = {},
  { draft = false, tags = [] }: GqlOptions = {},
): Promise<T> {
  const res = await fetch(process.env.CMS_GRAPHQL_URL!, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${draft ? process.env.CMS_PREVIEW_TOKEN : process.env.CMS_DELIVERY_TOKEN}`,
    },
    body: JSON.stringify({ query, variables }),
    ...(draft ? { cache: "no-store" as const } : { cache: "force-cache" as const, next: { tags } }),
  })
  const json = (await res.json()) as { data?: T; errors?: { message: string }[] }
  // status 200 bo'lsa ham xato bo'lishi mumkin
  if (json.errors?.length) throw new Error(json.errors.map((e) => e.message).join("; "))
  return json.data as T
}

