import "server-only"

const POST_QUERY = `
  query Post($slug: String!, $preview: Boolean!) {
    blogPostCollection(where: { slug: $slug }, limit: 1, preview: $preview) {
      items { sys { id } title slug body }
    }
  }
`

export async function getContentfulPost(slug: string, preview: boolean) {
  const space = process.env.CONTENTFUL_SPACE_ID
  const token = preview ? process.env.CONTENTFUL_PREVIEW_TOKEN : process.env.CONTENTFUL_DELIVERY_TOKEN
  const res = await fetch(`https://graphql.contentful.com/content/v1/spaces/${space}/environments/master`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body: JSON.stringify({ query: POST_QUERY, variables: { slug, preview } }),
    ...(preview
      ? { cache: "no-store" as const }
      : { cache: "force-cache" as const, next: { tags: ["posts", `post:${slug}`] } }),
  })
  const { data } = await res.json()
  return data?.blogPostCollection?.items?.[0] ?? null
}

