import "server-only"

type Article = { documentId: string; title: string; slug: string; content: string }
type StrapiList<T> = { data: T[]; meta: { pagination: { total: number } } }

export async function getStrapiArticle(slug: string, draft: boolean): Promise<Article | null> {
  const params = new URLSearchParams({
    "filters[slug][$eq]": slug,
    // Strapi 5: draft — oxirgi qoralama, published — chop etilgan versiya
    status: draft ? "draft" : "published",
  })
  const res = await fetch(`${process.env.STRAPI_URL}/api/articles?${params}`, {
    headers: { Authorization: `Bearer ${process.env.STRAPI_TOKEN}` },
    ...(draft
      ? { cache: "no-store" as const }
      : { cache: "force-cache" as const, next: { tags: ["articles", `article:${slug}`] } }),
  })
  if (!res.ok) throw new Error(`Strapi ${res.status}`)
  const json = (await res.json()) as StrapiList<Article>
  return json.data[0] ?? null
}

