import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

type Payload = { type: "post" | "author" | "settings"; slug?: string; id?: string }

function tagsFor(p: Payload): string[] {
  switch (p.type) {
    case "post":
      return p.slug ? ["posts", `post:${p.slug}`] : ["posts"]
    case "author":
      return [`author:${p.id}`]
    case "settings":
      return ["settings"]
  }
}

export async function POST(request: NextRequest) {
  if (request.headers.get("x-webhook-secret") !== process.env.REVALIDATE_SECRET) {
    return Response.json({ error: "Ruxsat yo'q" }, { status: 401 })
  }
  const tags = tagsFor((await request.json()) as Payload)
  for (const tag of tags) revalidateTag(tag, "max")
  return Response.json({ revalidated: true, tags })
}

