// fayl: app/api/webhooks/strapi/route.ts
import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

type StrapiEvent = {
  event: "entry.create" | "entry.update" | "entry.delete" | "entry.publish" | "entry.unpublish"
  model: string
  entry: { documentId: string; slug?: string }
}

const RELEVANT = new Set(["entry.publish", "entry.unpublish", "entry.delete"])

export async function POST(request: NextRequest) {
  // Strapi admin → Settings → Webhooks → Headers: Authorization: Bearer <secret>
  if (request.headers.get("authorization") !== `Bearer ${process.env.STRAPI_WEBHOOK_SECRET}`) {
    return new Response(null, { status: 401 })
  }
  const { event, model, entry } = (await request.json()) as StrapiEvent
  if (!RELEVANT.has(event)) return Response.json({ skipped: event })

  if (model === "article") {
    revalidateTag("articles", "max")
    if (entry.slug) revalidateTag(`article:${entry.slug}`, "max")
  }
  return Response.json({ revalidated: true, event, model })
}

