  const entry = (await request.json()) as ContentfulEntry
  const type = entry.sys.contentType.sys.id
  const slug = entry.fields?.slug?.["en-US"]

  const tags = [type === "blogPost" ? "posts" : type]
  if (slug) tags.push(`post:${slug}`)
  tags.forEach((tag) => revalidateTag(tag, "max"))
  return Response.json({ topic, tags })
}

