import { revalidateTag } from "next/cache"
import { parseBody } from "next-sanity/webhook"
import type { NextRequest } from "next/server"

type WebhookPayload = { _type: string; slug?: string }

export async function POST(request: NextRequest) {
  const { isValidSignature, body } = await parseBody<WebhookPayload>(
    request,
    process.env.SANITY_REVALIDATE_SECRET,
  )
  if (!isValidSignature) return Response.json({ message: "Imzo noto'g'ri" }, { status: 401 })
  if (!body?._type) return Response.json({ message: "_type yo'q" }, { status: 400 })

  revalidateTag(body._type, "max")
  if (body.slug) revalidateTag(`${body._type}:${body.slug}`, "max")
  return Response.json({ revalidated: true, type: body._type, slug: body.slug ?? null })
}

