import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

export async function POST(request: NextRequest) {
  if (request.headers.get("x-webhook-secret") !== process.env.REVALIDATE_SECRET) {
    return new Response(null, { status: 401 })
  }
  const { tag, urgent } = (await request.json()) as { tag: string; urgent?: boolean }

  if (urgent) {
    // muddat darhol tugaydi: keyingi tashrifchi yangi ma'lumotni kutib oladi
    revalidateTag(tag, { expire: 0 })
  } else {
    // keyingi tashrifchi eski versiyani tez oladi, yangisi fonda tayyorlanadi
    revalidateTag(tag, "max")
  }
  return Response.json({ tag, mode: urgent ? "expire" : "stale-while-revalidate" })
}

