// fayl: app/api/webhooks/bulk/route.ts
import { revalidateTag } from "next/cache"
import type { NextRequest } from "next/server"

type Doc = { type: string; slug?: string }

export async function POST(request: NextRequest) {
  if (request.headers.get("x-webhook-secret") !== process.env.REVALIDATE_SECRET) {
    return new Response(null, { status: 401 })
  }
  const { documents } = (await request.json()) as { documents?: Doc[] }
  if (!Array.isArray(documents) || documents.length === 0) {
    return Response.json({ error: "documents bo'sh" }, { status: 400 })
  }
  // bir nechta hujjat bitta ro'yxat tegiga tegishli — takrorlarni olib tashlaymiz
  const tags = new Set<string>()
  for (const doc of documents) {
    tags.add(`${doc.type}s`)
    if (doc.slug) tags.add(`${doc.type}:${doc.slug}`)
  }
  for (const tag of tags) revalidateTag(tag, "max")
  return Response.json({ count: tags.size, tags: [...tags].sort() })
}

