// fayl: lib/safe-headers.ts
const SECRET = new Set(['cookie', 'authorization', 'x-api-key'])

export function safeHeaders(headers: Record<string, string | string[] | undefined>) {
  const out: Record<string, string> = {}
  for (const [key, value] of Object.entries(headers)) {
    if (value === undefined) continue
    out[key] = SECRET.has(key.toLowerCase()) ? '[yashirildi]' : String(value)
  }
  return out
}

