import { trace } from '@opentelemetry/api'
import { cache, searchIndex } from './search-index'

const tracer = trace.getTracer('shop-web')

export async function search(term: string, page: number) {
  return tracer.startActiveSpan('search.query', async (span) => {
    span.setAttributes({ 'search.term': term, 'search.page': page })
    try {
      const cached = await cache.get(`${term}:${page}`)
      span.addEvent(cached ? 'cache.hit' : 'cache.miss')
      const results = cached ?? (await searchIndex(term, page))
      span.setAttribute('search.results', results.length)
      return results
    } finally {
      span.end()
    }
  })
}

