const tracer = trace.getTracer('shop-web')

function step<T>(name: string, fn: () => Promise<T>) {
  return tracer.startActiveSpan(name, async (span) => {
    try {
      return await fn()
    } finally {
      span.end()
    }
  })
}

export async function checkout(orderId: string) {
  return step('checkout', async () => {
    await step('checkout.reserve-stock', () => reserveStock(orderId))
    await step('checkout.charge', () => chargeCard(orderId))
    await step('checkout.send-receipt', () => sendReceipt(orderId))
    return { orderId, status: 'paid' }
  })
}

