// fayl: app/note-form.tsx
'use client'

import { useEffect, useState } from 'react'
import { saveNote } from './actions'

const KEY = 'pending-notes'
const readQueue = (): string[] => JSON.parse(localStorage.getItem(KEY) ?? '[]')

export function NoteForm() {
  const [status, setStatus] = useState('')

  useEffect(() => {
    async function flush() {
      const queue = readQueue()
      for (const text of queue) await saveNote(text)
      localStorage.removeItem(KEY)
      if (queue.length) setStatus(`${queue.length} ta eslatma yuborildi`)
    }
    if (navigator.onLine) flush()
    window.addEventListener('online', flush)
    return () => window.removeEventListener('online', flush)
  }, [])

  async function submit(formData: FormData) {
    const text = String(formData.get('text'))
    if (!navigator.onLine) {
      localStorage.setItem(KEY, JSON.stringify([...readQueue(), text]))
      setStatus("Oflayn: navbatga qo'yildi")
      return
    }
    await saveNote(text)
    setStatus('Saqlandi')
  }

  return (
    <form action={submit}>
      <input name="text" required />
      <button>Saqlash</button>
      <p>{status}</p>
    </form>
  )
}

