    icon: data.icon || '/icon-192x192.png',
    badge: '/badge-72x72.png',
    vibrate: [100, 50, 100],
    data: { url: data.url || '/' },
  }

  event.waitUntil(self.registration.showNotification(data.title, options))
})

// fayl: public/sw.js
self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const target = new URL(event.notification.data?.url || '/', self.location.origin).href

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
      const existing = windows.find((client) => client.url === target)
      if (existing) return existing.focus()
      return self.clients.openWindow(target)
    })()
  )
})

// fayl: app/push-manager.tsx
'use client'

import { useEffect, useState } from 'react'
import { subscribeUser, unsubscribeUser, sendNotification } from './actions'
import { urlBase64ToUint8Array } from '@/lib/url-base64'

export function PushNotificationManager() {
  const [isSupported, setIsSupported] = useState(false)
  const [subscription, setSubscription] = useState<PushSubscription | null>(null)
  const [message, setMessage] = useState('')

  useEffect(() => {
    if ('serviceWorker' in navigator && 'PushManager' in window) {
      setIsSupported(true)
      navigator.serviceWorker
        .register('/sw.js', { scope: '/', updateViaCache: 'none' })
        .then((reg) => reg.pushManager.getSubscription())
        .then(setSubscription)
    }
  }, [])

  async function subscribe() {
    const reg = await navigator.serviceWorker.ready
    const sub = await reg.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY!),
    })
    setSubscription(sub)
    await subscribeUser(JSON.parse(JSON.stringify(sub)))
  }

  async function unsubscribe() {
    await subscription?.unsubscribe()
    setSubscription(null)
    await unsubscribeUser()
  }

  async function sendTest() {
    if (!subscription) return
    await sendNotification(message)
    setMessage('')
  }

  if (!isSupported) return <p>Bu brauzerda push bildirishnomalar qo'llab-quvvatlanmaydi.</p>

  return (
    <section>
      <h3>Push bildirishnomalar</h3>
      {subscription ? (
        <>
          <p>Siz obuna bo'lgansiz.</p>
          <button onClick={unsubscribe}>Obunani bekor qilish</button>
          <input value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Xabar matni" />
          <button onClick={sendTest}>Sinov xabari</button>
        </>
      ) : (
        <>
          <p>Siz obuna bo'lmagansiz.</p>
          <button onClick={subscribe}>Obuna bo'lish</button>
        </>
      )}
    </section>
  )
}

// fayl: app/actions.ts
'use server'

import { db } from '@/lib/db'
import { auth } from '@/lib/auth'

type SubscriptionJSON = { endpoint: string; keys: { p256dh: string; auth: string } }

export async function subscribeUser(sub: SubscriptionJSON) {
  const session = await auth()
  if (!session) throw new Error('Avval tizimga kiring')

  const data = { p256dh: sub.keys.p256dh, auth: sub.keys.auth, userId: session.user.id }
  await db.pushSubscription.upsert({
    where: { endpoint: sub.endpoint },
    create: { endpoint: sub.endpoint, ...data },
    update: data,
  })
  return { success: true }
}

export async function unsubscribeUser(endpoint: string) {
  await db.pushSubscription.deleteMany({ where: { endpoint } })
  return { success: true }
}

// fayl: lib/notify.ts
import 'server-only'
import { WebPushError } from 'web-push'
import { webpush } from '@/lib/push'
import { db } from '@/lib/db'

export async function notifyAll(payload: { title: string; body: string; url?: string }) {
  const subs = await db.pushSubscription.findMany()
  const body = JSON.stringify(payload)

  const results = await Promise.allSettled(
    subs.map((s) =>
      webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, body)
    )
  )

  const dead: string[] = []
  results.forEach((result, i) => {
    if (result.status !== 'rejected') return
    const err = result.reason
    if (err instanceof WebPushError && (err.statusCode === 404 || err.statusCode === 410)) {
      dead.push(subs[i].endpoint)
    }
  })
  if (dead.length) await db.pushSubscription.deleteMany({ where: { endpoint: { in: dead } } })

  const sent = results.filter((r) => r.status === 'fulfilled').length
  return { sent, removed: dead.length }
}

