import { webpush } from '@/lib/push'
import { getSubscriptionsForUser } from '@/lib/subscriptions'

export async function notifyOrderReady(userId: string, orderId: string) {
  const subs = await getSubscriptionsForUser(userId)
  const payload = JSON.stringify({
    title: 'Buyurtma tayyor',
    body: `#${orderId} buyurtmangizni olib ketishingiz mumkin`,
    url: `/orders/${orderId}`,
  })

  await Promise.allSettled(
    subs.map((sub) =>
      webpush.sendNotification(sub, payload, {
        TTL: 60 * 30,
        urgency: 'high',
        topic: `order-${orderId}`,
      })
    )
  )
}

