'use client'

import { useEffect, useState } from 'react'

export function InstallPrompt() {
  const [isIOS, setIsIOS] = useState(false)
  const [isStandalone, setIsStandalone] = useState(false)

  useEffect(() => {
    const ua = navigator.userAgent
    const iPadOS = /Macintosh/.test(ua) && navigator.maxTouchPoints > 1
    setIsIOS(/iPad|iPhone|iPod/.test(ua) || iPadOS)
    setIsStandalone(window.matchMedia('(display-mode: standalone)').matches)
  }, [])

  if (isStandalone) return null

  return (
    <section>
      <h3>Ilovani o'rnating</h3>
      {isIOS && (
        <p>
          Safari'da "Ulashish" tugmasini bosing, so'ng "Bosh ekranga qo'shish" ni tanlang.
        </p>
      )}
    </section>
  )
}

// fayl: app/install-button.tsx
'use client'

import { useEffect, useState } from 'react'

type BeforeInstallPromptEvent = Event & {
  prompt: () => Promise<void>
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed'; platform: string }>
}

export function InstallButton() {
  const [deferred, setDeferred] = useState<BeforeInstallPromptEvent | null>(null)

  useEffect(() => {
    function onPrompt(e: Event) {
      e.preventDefault()
      setDeferred(e as BeforeInstallPromptEvent)
    }
    window.addEventListener('beforeinstallprompt', onPrompt)
    return () => window.removeEventListener('beforeinstallprompt', onPrompt)
  }, [])

  async function install() {
    if (!deferred) return
    await deferred.prompt()
    const { outcome } = await deferred.userChoice
    console.log('natija:', outcome)
    setDeferred(null)
  }

  if (!deferred) return null
  return <button onClick={install}>Ilovani o'rnatish</button>
}

// fayl: app/use-standalone.ts
import { useSyncExternalStore } from 'react'

const query = '(display-mode: standalone)'

function subscribe(callback: () => void) {
  const mql = window.matchMedia(query)
  mql.addEventListener('change', callback)
  window.addEventListener('appinstalled', callback)
  return () => {
    mql.removeEventListener('change', callback)
    window.removeEventListener('appinstalled', callback)
  }
}

function getSnapshot() {
  const iosStandalone = (navigator as Navigator & { standalone?: boolean }).standalone === true
  return window.matchMedia(query).matches || iosStandalone
}

export function useStandalone() {
  return useSyncExternalStore(subscribe, getSnapshot, () => false)
}

